CREATE TABLE inventory_restaurant_access (id BIGSERIAL PRIMARY KEY, restaurant_id UUID NOT NULL, auth_user_id UUID NOT NULL UNIQUE);
CREATE INDEX idx_inventory_access_restaurant ON inventory_restaurant_access(restaurant_id);
CREATE TABLE inventory_vendors (id BIGSERIAL PRIMARY KEY, restaurant_id UUID NOT NULL, name VARCHAR(200) NOT NULL, contact_name VARCHAR(200), phone VARCHAR(50), email VARCHAR(255), last_order_at TIMESTAMP, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL);
CREATE TABLE inventory_items (id BIGSERIAL PRIMARY KEY, restaurant_id UUID NOT NULL, name VARCHAR(200) NOT NULL, sku VARCHAR(100) NOT NULL, category VARCHAR(100), unit VARCHAR(50), stock_level NUMERIC(12,2) NOT NULL DEFAULT 0, minimum_stock NUMERIC(12,2) NOT NULL DEFAULT 0, unit_cost NUMERIC(12,2) NOT NULL DEFAULT 0, expiry_date DATE, status VARCHAR(30) NOT NULL, supplier VARCHAR(200), created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, CONSTRAINT uk_inventory_item_restaurant_sku UNIQUE(restaurant_id,sku));
CREATE INDEX idx_inventory_items_restaurant ON inventory_items(restaurant_id);
CREATE TABLE inventory_purchase_orders (id BIGSERIAL PRIMARY KEY, restaurant_id UUID NOT NULL, vendor_id BIGINT NOT NULL REFERENCES inventory_vendors(id), status VARCHAR(30) NOT NULL, estimated_total NUMERIC(12,2) NOT NULL DEFAULT 0, notes TEXT, created_at TIMESTAMP NOT NULL);
CREATE TABLE inventory_purchase_order_items (id BIGSERIAL PRIMARY KEY, purchase_order_id BIGINT NOT NULL REFERENCES inventory_purchase_orders(id) ON DELETE CASCADE, inventory_item_id BIGINT NOT NULL REFERENCES inventory_items(id), quantity NUMERIC(12,2) NOT NULL, unit_price NUMERIC(12,2) NOT NULL);
